// Merge all financial data and calculate metrics
const monthData = $('Code - Get Month Range').first().json;
const revenueItems = $('Notion - Get Revenue').all() || [];
const expenseItems = $('Notion - Get Expenses').all() || [];
const feeItems = $('Notion - Get Stripe Fees').all() || [];

// Calculate revenue
const incomes = revenueItems.map(i => i.json);
const totalRevenue = incomes.reduce((sum, income) => 
  sum + (income.properties?.Amount?.number || 0), 0
);

// Calculate Stripe fees (negative amounts)
const fees = feeItems.map(f => f.json);
const totalStripeFees = Math.abs(
  fees.reduce((sum, fee) => sum + (fee.properties?.Amount?.number || 0), 0)
);

// Calculate expenses by category
const expenses = expenseItems.map(e => e.json);
const expensesByCategory = {};
let totalExpenses = 0;

expenses.forEach(expense => {
  const amount = expense.properties?.Amount?.number || 0;
  totalExpenses += amount;

  // Get category name (simplified - would need relation lookup in production)
  const category = expense.properties?.Categories?.relation?.[0]?.id || 'Uncategorized';
  const merchant = expense.properties?.Expense?.title?.[0]?.plain_text || 'Unknown';
  const date = expense.properties?.Date?.date?.start || '';
  const receiptStatus = expense.properties?.['Receipt Status']?.select?.name || 'Unknown';

  if (!expensesByCategory[category]) {
    expensesByCategory[category] = {
      total: 0,
      count: 0,
      items: []
    };
  }

  expensesByCategory[category].total += amount;
  expensesByCategory[category].count++;
  expensesByCategory[category].items.push({
    merchant,
    amount,
    date,
    receiptStatus
  });
});

// Sort categories by total
const sortedCategories = Object.entries(expensesByCategory)
  .sort((a, b) => b[1].total - a[1].total)
  .map(([name, data]) => ({
    name,
    ...data,
    percentage: totalExpenses > 0 ? (data.total / totalExpenses * 100).toFixed(1) : 0
  }));

// Net profit
const netProfit = totalRevenue - totalExpenses - totalStripeFees;
const profitMargin = totalRevenue > 0 
  ? (netProfit / totalRevenue * 100).toFixed(1)
  : 0;

// Missing receipts
const missingReceipts = expenses.filter(exp => 
  exp.properties?.['Receipt Status']?.select?.name === 'Pending'
);
const missingReceiptsTotal = missingReceipts.reduce((sum, exp) => 
  sum + (exp.properties?.Amount?.number || 0), 0
);

// Top customers (from revenue)
const customerRevenue = {};
incomes.forEach(income => {
  const customer = income.properties?.Customer?.rich_text?.[0]?.plain_text || 'Unknown';
  const amount = income.properties?.Amount?.number || 0;
  customerRevenue[customer] = (customerRevenue[customer] || 0) + amount;
});

const topCustomers = Object.entries(customerRevenue)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([name, amount]) => ({ name, amount }));

return [{
  json: {
    ...monthData,
    metrics: {
      totalRevenue,
      totalStripeFees,
      totalExpenses,
      netProfit,
      profitMargin,
      revenueCount: incomes.length,
      expenseCount: expenses.length
    },
    sortedCategories,
    topCustomers,
    missingReceipts: {
      count: missingReceipts.length,
      total: missingReceiptsTotal,
      items: missingReceipts.map(exp => ({
        merchant: exp.properties?.Expense?.title?.[0]?.plain_text || 'Unknown',
        amount: exp.properties?.Amount?.number || 0,
        url: exp.url
      }))
    }
  }
}];

// Generate Notion report content
const data = $input.first().json;
const { metrics, sortedCategories, topCustomers, missingReceipts, monthName } = data;

let reportContent = `# Finance Report - ${monthName}\n\n`;

reportContent += `## Summary\n\n`;
reportContent += `**Revenue:** $${metrics.totalRevenue.toFixed(2)}\n`;
reportContent += `**Expenses:** $${metrics.totalExpenses.toFixed(2)}\n`;
reportContent += `**Stripe Fees:** $${metrics.totalStripeFees.toFixed(2)}\n`;
reportContent += `**Net Profit:** $${metrics.netProfit.toFixed(2)} (${metrics.profitMargin}% margin)\n\n`;

reportContent += `---\n\n`;

reportContent += `## Revenue Breakdown\n\n`;
reportContent += `**Total Customer Payments:** $${metrics.totalRevenue.toFixed(2)}\n`;
reportContent += `**Number of Transactions:** ${metrics.revenueCount}\n`;
reportContent += `**Average Transaction:** $${metrics.revenueCount > 0 ? (metrics.totalRevenue / metrics.revenueCount).toFixed(2) : '0.00'}\n\n`;

if (topCustomers.length > 0) {
  reportContent += `### Top Customers\n\n`;
  topCustomers.forEach((c, i) => {
    reportContent += `${i + 1}. ${c.name}: $${c.amount.toFixed(2)}\n`;
  });
  reportContent += `\n`;
}

reportContent += `---\n\n`;

reportContent += `## Expense Breakdown by Category\n\n`;
sortedCategories.forEach(cat => {
  reportContent += `### ${cat.name} - $${cat.total.toFixed(2)} (${cat.percentage}%)\n`;
  reportContent += `- ${cat.count} transactions\n`;
  reportContent += `- Average: $${(cat.total / cat.count).toFixed(2)}\n\n`;

  // Top 3 expenses in category
  const topItems = cat.items.sort((a, b) => b.amount - a.amount).slice(0, 3);
  reportContent += `Top expenses:\n`;
  topItems.forEach((item, i) => {
    reportContent += `${i + 1}. ${item.merchant} - $${item.amount.toFixed(2)}\n`;
  });
  reportContent += `\n`;
});

reportContent += `---\n\n`;

reportContent += `## Action Items\n\n`;
if (missingReceipts.count > 0) {
  reportContent += `:warning: **Missing Receipts:** ${missingReceipts.count} expenses ($${missingReceipts.total.toFixed(2)})\n\n`;
  missingReceipts.items.forEach(item => {
    reportContent += `- ${item.merchant}: $${item.amount.toFixed(2)}\n`;
  });
}

return [{
  json: {
    ...data,
    reportContent
  }
}];

// Format Slack summary
const data = $input.first().json;
const { metrics, sortedCategories, missingReceipts, monthName } = data;

let message = `:bar_chart: *${monthName} Finance Report*\n\n`;
message += `*Revenue:* $${metrics.totalRevenue.toFixed(2)}\n`;
message += `*Expenses:* $${metrics.totalExpenses.toFixed(2)}\n`;
message += `*Net Profit:* *$${metrics.netProfit.toFixed(2)}* (${metrics.profitMargin}% margin)\n\n`;

message += `*Top Categories:*\n`;
sortedCategories.slice(0, 3).forEach((cat, i) => {
  message += `${i + 1}. ${cat.name}: $${cat.total.toFixed(2)} (${cat.percentage}%)\n`;
});
message += `\n`;

message += `:warning: *Action Items:*\n`;
message += `• ${missingReceipts.count} receipts missing ($${missingReceipts.total.toFixed(2)})\n\n`;

message += `<https://notion.so|View Full Report>`;

return [{
  json: {
    ...data,
    slackMessage: message
  }
}];
